/* Planejamento Medicina 2.0 — independent, client-side implementation.
   Account sync uses a dedicated Supabase table; it never writes to Google Sheets or MedReview records. */
'use strict';
const ZONE='America/Cuiaba', STORAGE='planejamento-medicina-2.0-personal-local';
const MENU=[['today','today','Hoje'],['week','week','Semana'],['calendar','calendar','Cronograma'],['timeline','timeline','Linha do Tempo'],['tasks','tasks','Tarefas'],['focus','focus','Foco'],['studies','studies','Estudos'],['reviews','reviews','Revisões'],['exams','exams','Avaliações'],['reports','reports','Desempenho'],['materials','materials','Materiais'],['planner','planner','Planejador'],['settings','settings','Configurações']];
let academicStatus='loading',academicSource=null;
let semesterMonth='all',semesterType='all';
let seed=[],page='today',weekOffset=0,taskFilter='pending',proposed=[],timer=25*60,focusLength=25,interval=null,focusTopic='',focusSubject='';
const $=id=>document.getElementById(id);const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const esc=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayAdd=(d,n)=>{let v=new Date(d+'T12:00:00Z');v.setUTCDate(v.getUTCDate()+n);return v.toISOString().slice(0,10)};
