  const head='<div class="week-head"><div class="pill-row">'+btn(ico('chevron-left'),'prev-week','aria-label="Semana anterior"')+btn('Esta semana','reset-week')+btn(ico('chevron'),'next-week','aria-label="Próxima semana"')+'</div>'+tag(fmt(days[0])+' — '+fmt(days[6]))+'</div>';
  const tabs='<div class="week-tabs" role="tablist" aria-label="Dias da semana">'+days.map(d=>'<button type="button" role="tab" aria-selected="'+(d===weekSelected)+'" class="'+(d===weekSelected?'active':'')+(d===t?' is-today':'')+'" data-action="week-day" data-date="'+d+'"><small>'+esc(fmt(d,{weekday:'short',timeZone:'UTC'}).replace('.',''))+'</small><strong>'+Number(d.slice(8))+'</strong></button>').join('')+'</div>';
  const gutter='<div class="cal-gutter" aria-hidden="true"><div class="cal-day-head"></div><div class="cal-allday" style="min-height:'+alldayH+'px"></div><div class="cal-gutter-body" style="height:'+height+'px">'+Array.from({length:endH-startH},(_,i)=>'<span style="top:'+(i*HOUR_PX)+'px">'+String(startH+i).padStart(2,'0')+':00</span>').join('')+'</div></div>';
