function reportView(){let m=metrics(),days=Array.from({length:14},(_,i)=>dayAdd(today(),i-13));let trend=days.map(d=>data.sessions.filter(x=>x.date===d).reduce((s,x)=>s+Number(x.minutes||0),0)),max=Math.max(60,...trend);const wDays=['dom','seg','ter','qua','qui','sex','sáb'];let chart='<div class="chart">'+days.map((d,i)=>{const isToday=d===today();const wDay=wDays[new Date(d+'T12:00:00Z').getUTCDay()];return '<div class="chart-column '+(isToday?'today':'')+'"><div title="'+fmt(d)+' ('+wDay+') • '+trend[i]+' min" style="height:'+Math.max(3,Math.round(trend[i]/max*145))+'px"></div><small><span>'+wDay+'</span><span>'+d.slice(-2)+'</span></small></div>'}).join('')+'</div>';let by={};for(const x of data.sessions)by[x.subject]=(by[x.subject]||0)+Number(x.minutes||0);let groups=Object.entries(by).sort((a,b)=>b[1]-a[1]);let ymax=Math.max(1,...groups.map(x=>x[1]));return statCards()+consistencyPanel()+'<div class="cols"><div>'+panel('Últimos 14 dias',chart+'<p class="tiny">Minutos registrados por dia. Aulas previstas não entram na contabilização.</p>')+panel('Tempo por disciplina',groups.length?groups.map(x=>'<div class="bar-row"><span>'+esc(x[0])+'</span><div class="bar"><i style="width:'+pct(x[1],ymax)+'%"></i></div><b>'+hours(x[1])+'</b></div>').join(''):empty('Registre estudos para visualizar a distribuição.'))+'</div><div>'+panel('Qualidade do aprendizado','<div class="stat-main">'+(m.accuracy===null?'—':m.accuracy+'%')+'</div><p class="tiny">Taxa de acerto em '+m.q+' questões informadas.</p><div class="progress"><div class="progress-inner" style="width:'+(m.accuracy||0)+'%"></div></div><div class="panel-section"><strong>'+data.reviews.filter(x=>x.done).length+'</strong> <span class="tiny">revisões concluídas</span></div><div class="panel-section"><strong>'+data.tasks.filter(x=>x.done).length+'</strong> <span class="tiny">tarefas realizadas</span></div>')+mistakeTopicsPanel()+'</div></div>'}
function materialsView(){const existing=data.materials.length?'<details class="settings-fold"><summary>Links que você já salvou · '+data.materials.length+'</summary><div class="fold-content">'+data.materials.map(x=>'<div class="source-box"><span class="source-icon">'+ico('materials')+'</span><div style="flex:1"><strong>'+esc(x.title)+'</strong><p>'+esc(x.subject||'Geral')+'</p>'+(typeof x.url==='string'&&/^https:\/\//i.test(x.url)?'<a class="surface-link" target="_blank" rel="noopener noreferrer" href="'+esc(x.url)+'">Abrir material ↗</a>':'')+'</div>'+btn('Excluir','delete','data-type="material" data-id="'+esc(x.id)+'"','btn btn-small btn-danger')+'</div>').join('')+'</div></details>':'';const url=data.settings.materialsUrl||'';return panel('Seus materiais no Google Drive',/^https:\/\/drive\.google\.com\//i.test(url)?'<p class="muted">Seus materiais ficam na sua pasta do Drive.</p><a class="btn btn-primary materials-drive-link" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">Abrir pasta de materiais ↗</a>':empty('Você ainda não cadastrou uma pasta de materiais.')+btn('Adicionar meu Drive','navigate','data-page="settings"'))+existing}

/* Foco: o tempo é calculado pelo relógio (horário de término guardado), então sobrevive a abas em segundo plano, recarregar e fechar o app. */
let focusMode='focus',focusEndsAt=null,focusTaskId='',focusFinished=null,focusAudio=null;
const focusKey=()=>STORAGE+'-focus';
const focusBreakLength=()=>[5,10,15].includes(Number(data.settings.focusBreak))?Number(data.settings.focusBreak):5;
function focusPersist(){try{if(!focusEndsAt&&timer===focusLength*60&&focusMode==='focus'&&!focusTaskId)localStorage.removeItem(focusKey());else localStorage.setItem(focusKey(),JSON.stringify({mode:focusMode,length:focusLength,endsAt:focusEndsAt,left:timer,subject:focusSubject,topic:focusTopic,taskId:focusTaskId}))}catch{}}
function focusRestore(){let s;try{s=JSON.parse(localStorage.getItem(focusKey())||'null')}catch{}if(!s||typeof s!=='object')return;focusMode=s.mode==='break'?'break':'focus';focusLength=Number(s.length)||25;focusSubject=String(s.subject||'');focusTopic=String(s.topic||'');focusTaskId=String(s.taskId||'');
  if(s.endsAt){const left=Math.round((Number(s.endsAt)-Date.now())/1000);if(left>0){focusEndsAt=Number(s.endsAt);timer=left;interval=setInterval(focusTick,1000)}else{timer=0;focusEndsAt=null;focusComplete(true)}}else timer=Math.max(0,Math.min(focusLength*60,Number(s.left)||focusLength*60))}
function focusTitle(){document.title=focusEndsAt?clock(timer)+' · '+(focusMode==='break'?'Pausa':'Foco')+' · Planejamento':'Planejamento Medicina · Central Acadêmica'}
function focusPaint(){const el=$('timer-display');if(el)el.textContent=clock(timer);const ring=document.querySelector('.focus-clock');if(ring)ring.style.setProperty('--p',String(100-Math.round(100*timer/Math.max(1,focusLength*60))));focusTitle()}
function focusTick(){if(!focusEndsAt)return;timer=Math.max(0,Math.round((focusEndsAt-Date.now())/1000));focusPaint();if(!timer)focusComplete(false)}
function focusChime(){if(!data.settings.focusSound)return;try{focusAudio=focusAudio||new (window.AudioContext||window.webkitAudioContext)();const ctx=focusAudio,now=ctx.currentTime;[0,.28,.56].forEach((d,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=i===2?880:660;g.gain.setValueAtTime(.0001,now+d);g.gain.exponentialRampToValueAtTime(.22,now+d+.02);g.gain.exponentialRampToValueAtTime(.0001,now+d+.24);o.connect(g).connect(ctx.destination);o.start(now+d);o.stop(now+d+.26)})}catch{}}
function focusComplete(whileClosed){if(interval)clearInterval(interval);interval=null;const mode=focusMode,length=focusLength;focusEndsAt=null;
  if(mode==='focus'){focusFinished={minutes:length,subject:focusSubject,topic:focusTopic,taskId:focusTaskId};addFocusTime(focusTaskId,length);focusMode='focus';timer=focusLength*60;focusPersist();focusTitle();focusChime();
    notify(whileClosed?'Seu bloco de foco terminou enquanto o app estava fechado.':'Bloco de foco concluído.',{label:'Registrar '+length+' min',run:()=>registerFinished()});if(page==='focus')render()}
  else{focusMode='focus';focusLength=focusLength===focusBreakLength()?25:focusLength;timer=focusLength*60;focusPersist();focusTitle();focusChime();notify('Pausa encerrada. Pronto para o próximo bloco?');if(page==='focus')render()}}
function addFocusTime(taskId,minutes){const x=taskId&&data.tasks.find(t=>t.id===taskId);if(x&&minutes>0){x.spent=Math.round((Number(x.spent)||0)+minutes);save()}}
function registerFinished(){const f=focusFinished;focusFinished=null;if(!f)return;openForm('study',{subject:f.subject,topic:f.topic,minutes:Math.max(1,f.minutes),date:today()})}
function changeTimer(n){if(interval)clearInterval(interval);interval=null;focusEndsAt=null;focusMode='focus';focusLength=n;timer=n*60;focusPersist();focusTitle();render()}
function timerToggle(){focusSubject=$('focus-subject')?.value??focusSubject;focusTopic=$('focus-topic')?.value??focusTopic;
  if(focusEndsAt){timer=Math.max(0,Math.round((focusEndsAt-Date.now())/1000));focusEndsAt=null;if(interval)clearInterval(interval);interval=null;focusPersist();focusTitle();render();return}
  if(data.settings.focusSound){try{focusAudio=focusAudio||new (window.AudioContext||window.webkitAudioContext)();focusAudio.resume?.()}catch{}}
  if(!timer)timer=focusLength*60;focusEndsAt=Date.now()+timer*1000;interval=setInterval(focusTick,1000);focusPersist();focusTitle();render()}
function timerFinish(){focusSubject=$('focus-subject')?.value??focusSubject;focusTopic=$('focus-topic')?.value??focusTopic;if(focusEndsAt)timer=Math.max(0,Math.round((focusEndsAt-Date.now())/1000));const actual=focusMode==='focus'?Math.max(1,Math.ceil((focusLength*60-timer)/60)):0;if(interval)clearInterval(interval);interval=null;focusEndsAt=null;if(focusMode==='focus')addFocusTime(focusTaskId,actual);const seed={subject:focusSubject,topic:focusTopic,minutes:Math.max(actual,1),date:today()};focusMode='focus';timer=focusLength*60;focusTaskId='';focusPersist();focusTitle();openForm('study',seed)}
function timerReset(){if(interval)clearInterval(interval);interval=null;focusEndsAt=null;focusMode='focus';timer=focusLength*60;focusPersist();focusTitle();render()}
function startBreak(){if(interval)clearInterval(interval);focusMode='break';focusLength=focusBreakLength();timer=focusLength*60;focusEndsAt=Date.now()+timer*1000;interval=setInterval(focusTick,1000);focusPersist();focusTitle();render()}
function focusView(){const running=Boolean(focusEndsAt),pct=100-Math.round(100*timer/Math.max(1,focusLength*60)),task=focusTaskId&&data.tasks.find(t=>t.id===focusTaskId),brk=focusBreakLength();
  const lengths=focusMode==='break'?'':'<div class="pill-row focus-lengths" role="group" aria-label="Duração do bloco">'+[25,50,90].map(n=>btn(n+' min','timer-length','data-min="'+n+'" aria-pressed="'+(focusLength===n)+'"',focusLength===n?'btn btn-primary':'btn')).join('')+'</div>';
  const finished=focusFinished&&!running?'<div class="focus-done"><div><strong>Bloco de '+focusFinished.minutes+' min concluído</strong><small>'+esc([focusFinished.subject,focusFinished.topic].filter(Boolean).join(' · ')||'Registre o que você estudou.')+'</small></div><div class="pill-row">'+btn(ico('plus')+'Registrar estudo','focus-register','','btn btn-primary')+btn(ico('coffee')+'Pausa de '+brk+' min','focus-break')+'</div></div>':'';
  const taskLine=task?'<p class="focus-task">'+ico('tasks')+'<span>Tarefa: <strong>'+esc(task.title)+'</strong>'+(Number(task.estimate)?' · '+(Number(task.spent)||0)+' de '+esc(task.estimate)+' min estimados':'')+'</span></p>':'';
  const prefs='<div class="focus-prefs"><label class="field-label">Pausa entre blocos<select class="field" id="focus-break">'+[5,10,15].map(n=>'<option value="'+n+'" '+(n===brk?'selected':'')+'>'+n+' min</option>').join('')+'</select></label><label class="focus-sound"><input type="checkbox" id="focus-sound" '+(data.settings.focusSound?'checked':'')+'> '+ico('volume')+'Som ao terminar</label></div>';
  return panel(focusMode==='break'?'Pausa':'Concentração sem distrações',finished+'<div class="focus-area">'+tag(focusMode==='break'?'Pausa':running?'Em foco':'Modo foco',focusMode==='break'?'good':'')+'<div class="focus-clock'+(running?' is-running':'')+(focusMode==='break'?' is-break':'')+'" style="--p:'+pct+'"><strong id="timer-display">'+clock(timer)+'</strong><small>'+(focusMode==='break'?'Levante, beba água, descanse os olhos':running?'Termina às '+new Intl.DateTimeFormat('pt-BR',{timeZone:ZONE,hour:'2-digit',minute:'2-digit'}).format(new Date(focusEndsAt)):'Escolha um bloco de estudo')+'</small></div>'+lengths+taskLine+(focusMode==='break'?'':'<div class="form-grid" style="margin-top:18px"><label class="field-label">Disciplina<input class="field" id="focus-subject" placeholder="Ex.: Fisiologia" value="'+esc(focusSubject)+'"></label><label class="field-label">Assunto<input class="field" id="focus-topic" placeholder="Ex.: Controle da pressão arterial" value="'+esc(focusTopic)+'"></label></div>')+'<div class="pill-row focus-actions">'+btn(ico(running?'pause':'play')+(running?'Pausar':timer<focusLength*60?'Continuar':'Iniciar'),'timer-toggle','','btn btn-primary')+(focusMode==='break'?btn('Encerrar pausa','timer-reset'):btn(ico('check')+'Concluir e registrar','timer-finish')+btn(ico('rotate')+'Reiniciar','timer-reset'))+'</div><p class="tiny">O tempo só entra nos relatórios depois que você confirma o registro. O cronômetro continua certo mesmo com a aba em segundo plano ou o app fechado.</p>'+prefs+'</div>')}
const clock=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
function suggest(){let av=data.settings.availability||{},suggestions=[],missed=[],free={};if(!Object.keys(av).length)return {suggestions,missed,reason:'Configure a disponibilidade nas Configurações.'};const e=events().filter(x=>x.from&&x.to&&x.type!=='review'&&x.type!=='free'&&x.origin!=='planned');for(let i=0;i<7;i++){let d=dayAdd(today(),i),weekday=new Date(d+'T12:00:00Z').getUTCDay(),a=av[weekday];if(!a)continue;let st=mins(a.from),en=mins(a.to);if(st>=en)continue;let blocks=e.filter(x=>x.date===d).map(x=>[mins(x.from),mins(x.to)]).concat(data.tasks.filter(x=>x.scheduled===d).map(x=>[mins(x.start),mins(x.end)])).sort((a,b)=>a[0]-b[0]),cursor=st;free[d]=[];for(let [s,t] of blocks){if(s>cursor)free[d].push([cursor,Math.min(s,en)]);cursor=Math.max(cursor,t)}if(cursor<en)free[d].push([cursor,en]);}
let tasks=data.tasks.filter(x=>!x.done&&!x.scheduled).sort((a,b)=>Number(b.priority)-Number(a.priority)||(a.date||'9999').localeCompare(b.date||'9999'));for(let task of tasks){let duration=Number(task.estimate||0),slot=null;if(duration<=0){missed.push({title:task.title,why:'Duração não informada'});continue}for(let [d,intervals] of Object.entries(free).sort((a,b)=>a[0].localeCompare(b[0]))){if(task.date&&d>task.date)continue;for(let it of intervals)if(it[1]-it[0]>=duration){slot={id:task.id,title:task.title,date:d,start:time(it[0]),end:time(it[0]+duration)};it[0]+=duration+10;break}if(slot)break}if(slot)suggestions.push(slot);else missed.push({title:task.title,why:'Sem espaço livre antes do prazo'})}return {suggestions,missed,reason:null}}
function availabilityEditor(){const a=data.settings.availability||{},days=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];return '<div class="availability-editor">'+days.map((day,i)=>'<div class="availability-row"><strong>'+day+'</strong><label class="field-label">De<input class="field" type="time" aria-label="Início '+day+'" id="start-'+i+'" value="'+esc(a[i]?.from||'')+'"></label><label class="field-label">Até<input class="field" type="time" aria-label="Fim '+day+'" id="end-'+i+'" value="'+esc(a[i]?.to||'')+'"></label>'+btn('Limpar','availability-clear','data-day="'+i+'" aria-label="Limpar horários de '+day+'"')+'</div>').join('')+'</div><p class="tiny">Preencha apenas os dias em que pode estudar. Deixe os dois horários vazios nos dias sem disponibilidade.</p>'+btn('Salvar horários','save-availability','','btn btn-primary')}
let plannerExcluded=new Set();
function plannerView(){const plan=suggest(),pending=data.tasks.filter(x=>!x.done&&!x.scheduled),scheduled=data.tasks.filter(x=>!x.done&&x.scheduled&&x.scheduled>=today()).sort((a,b)=>a.scheduled.localeCompare(b.scheduled)||(a.start||'').localeCompare(b.start||'')),available=Object.keys(data.settings.availability||{}).length;const ids=new Set(plan.suggestions.map(x=>x.id));plannerExcluded=new Set([...plannerExcluded].filter(id=>ids.has(id)));proposed=plan.suggestions.filter(x=>!plannerExcluded.has(x.id));const total=proposed.reduce((sum,x)=>sum+mins(x.end)-mins(x.start),0);const weekdays=Array.from({length:7},(_,i)=>dayAdd(today(),i));const board=weekdays.map(date=>{const suggestions=plan.suggestions.filter(x=>x.date===date),existing=scheduled.filter(x=>x.scheduled===date);return '<section class="planner-day"><header><strong>'+fmt(date,{weekday:'short',day:'2-digit',month:'short',timeZone:'UTC'})+'</strong>'+tag(date===today()?'Hoje':suggestions.length+' sugestões',date===today()?'':'gray')+'</header>'+(existing.map(x=>'<div class="planner-slot existing"><span class="tiny">Já reservado · '+esc(x.start||'')+'–'+esc(x.end||'')+'</span><strong>'+esc(x.title)+'</strong>'+btn('Retirar horário','task-unschedule','data-id="'+esc(x.id)+'"')+'</div>').join(''))+(suggestions.map(x=>{const task=data.tasks.find(t=>t.id===x.id);return '<label class="planner-slot suggested"><input type="checkbox" data-planner-id="'+esc(x.id)+'" '+(!plannerExcluded.has(x.id)?'checked':'')+'><span><span class="planner-slot-time">'+esc(x.start)+'–'+esc(x.end)+'</span><strong>'+esc(x.title)+'</strong><small>'+esc(task?.subject||'Geral')+' · '+(mins(x.end)-mins(x.start))+' min</small><small>Prioridade '+(String(task?.priority)==='3'?'alta':String(task?.priority)==='2'?'média':'normal')+(task?.date?' · prazo '+fmt(task.date):' · sem prazo')+'</small></span></label>'}).join(''))+(!suggestions.length&&!existing.length?'<p class="tiny">Sem blocos de tarefas neste dia.</p>':'')+'</section>'}).join('');const misses=plan.missed.map(x=>{const task=data.tasks.find(t=>t.id===x.id);const canSplit=Number(task?.estimate)>=40;return '<div class="planner-missed"><div><strong>'+esc(x.title)+'</strong><p class="tiny">'+esc(x.why)+'</p></div><div class="pill-row">'+(canSplit?btn('Dividir em 2 blocos','task-split','data-id="'+esc(x.id||'')+'"'):'')+btn('Ajustar tarefa','task-edit','data-id="'+esc(x.id||'')+'"')+'</div></div>'}).join('');return panel('Monte sua semana de estudo','<p class="muted">O planejador procura horários para as suas tarefas nos próximos sete dias, respeitando as aulas, os compromissos e a disponibilidade que você informou.</p><div class="planner-steps"><span><b>1</b> Defina seus horários livres</span><span><b>2</b> Confira os blocos sugeridos</span><span><b>3</b> Escolha e salve na agenda</span></div><div class="pill-row">'+btn('Criar tarefa','create','data-type="task"')+btn('Recalcular sugestões','refresh')+btn('Ver agenda semanal','navigate','data-page="week"')+'</div>')+'<details class="settings-fold planner-availability" '+(!available?'open':'')+'><summary><span>Seus horários disponíveis</span><small>'+available+' dias configurados · clique para ajustar</small></summary><div class="fold-content">'+availabilityEditor()+'</div></details><div class="task-summary"><div><strong>'+pending.length+'</strong><span>Tarefas a encaixar</span></div><div><strong>'+proposed.length+'</strong><span>Sugestões selecionadas</span></div><div><strong>'+total+' min</strong><span>Tempo selecionado</span></div><div><strong>'+plan.missed.length+'</strong><span>Precisam de ajuste</span></div></div>'+(!available?panel('Comece pelos seus horários',empty('Informe sua disponibilidade acima e clique em Salvar horários para gerar sugestões.')):!pending.length?panel('Sua lista está organizada',empty(scheduled.length?'As tarefas com horário reservado aparecem abaixo. Crie novas tarefas para receber sugestões.':'Crie uma tarefa com duração estimada para montar o primeiro bloco.')):'')+(available?panel('Prévia dos próximos sete dias','<p class="tiny">Marque os blocos que deseja salvar. “Já reservado” identifica tarefas que já estão na sua agenda.</p><div class="planner-board">'+board+'</div><div class="planner-save"><div><strong>'+proposed.length+' blocos selecionados · '+total+' min</strong><small>Ao salvar, eles aparecem em Semana e nas suas tarefas.</small></div><button type="button" class="btn btn-primary" data-action="apply" '+(!proposed.length?'disabled':'')+'>Salvar blocos na agenda</button></div>'):'')+(misses?panel('O que precisa de ajuste',misses):'')+'<details class="settings-fold"><summary>Como os horários são escolhidos?</summary><div class="fold-content"><p class="tiny">As tarefas são ordenadas por prioridade, proximidade de provas da disciplina e prazo. Cada tarefa precisa caber inteira em um intervalo livre. Aulas e compromissos são respeitados, com 10 minutos entre as novas sugestões. Hoje, só entram horários que ainda não passaram.</p><p class="tiny">Se uma tarefa for longa demais, divida-a em ações menores. Salvar um bloco reserva tempo; registrar o estudo depois informa o que você realmente fez.</p></div></details>'}
function scheduleSettings(){
  if(personalAccount())return panel('Seu cronograma do semestre','<p class="muted">Importe a sua planilha. O site organiza as aulas, provas, horários livres e atividades na Semana e no Cronograma da sua conta.</p><p class="tiny">'+esc(academicSummary())+'</p><label class="field-label">Planilha do semestre<input type="file" id="semester-upload" class="field" accept=".pdf,.xlsx,.csv,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv"></label><p class="tiny">PDF com grade e texto selecionável, Excel ou CSV · até 3 MB. Você confere uma prévia antes de salvar. O arquivo original não fica armazenado.</p><p id="semester-import-status" role="status" class="tiny"></p>'+btn('Baixar modelo CSV','semester-import-template')+(data.replacement.length?btn('Remover meu cronograma','reset-schedule','','btn btn-danger'):'')+'<h3>Pasta dos seus materiais</h3><label class="field-label">Link do Google Drive<input id="materials-url" class="field" type="url" value="'+esc(data.settings.materialsUrl||'')+'" placeholder="https://drive.google.com/drive/folders/..."></label>'+btn('Salvar link dos materiais','materials-link-save')+'<p class="tiny">Use uma pasta sua. O link acompanha sua conta em todos os dispositivos.</p>');
  return panel('Cronograma do semestre','<div class="source-box"><span class="source-icon">'+ico('calendar')+'</span><div><strong>UC2'+(academicSource?.semester?' · Semestre '+esc(academicSource.semester):'')+'</strong><p>'+esc(academicSummary())+'</p>'+(academicSource?'<a href="./data/uc2-2026-2.pdf" target="_blank" rel="noopener noreferrer" class="surface-link">Ver planilha do semestre (PDF) ↗</a>':'')+'</div></div><label class="field-label">Importar outro cronograma (CSV)<input type="file" id="csv-upload" class="field" accept=".csv,text/csv"></label><p class="tiny">Importação local do cronograma.</p>'+btn('Usar cronograma incluído no site','reset-schedule')+'<h3>Pasta dos seus materiais</h3><label class="field-label">Link do Google Drive<input id="materials-url" class="field" type="url" value="'+esc(data.settings.materialsUrl||'')+'" placeholder="https://drive.google.com/drive/folders/..."></label>'+btn('Salvar link dos materiais','materials-link-save')+'<p class="tiny">Use uma pasta sua.</p>');
}
function settingsView(){return '<div class="settings-intro"><h2>Ajuste seu planejamento</h2><p class="muted">Seus horários, sua meta e seus dados em um só lugar.</p></div><div class="settings-grid"><div>'+panel('Quando você pode estudar?','<p class="tiny">Esta disponibilidade é usada pelo planejador para sugerir blocos de estudo.</p>'+availabilityEditor())+'</div><div>'+panel('Sua meta de estudo','<label class="field-label">Horas de estudo por semana<input id="goal" class="field" type="number" min="1" max="168" value="'+esc(data.settings.goal)+'"></label><p class="tiny">O progresso considera apenas sessões de estudo registradas.</p><h3 class="settings-subtitle">Revisões de estudo planejadas</h3><p class="tiny">Opcional: após registrar uma sessão, criar lembretes de revisão nestes intervalos. Os flashcards do MedReview continuam sendo consultados separadamente.</p><label class="field-label">Dias após a sessão<input id="intervals" class="field" value="'+esc(data.settings.intervals)+'" placeholder="Ex.: 1, 7, 30"></label><div class="pill-row interval-presets"><span class="tiny">Sugestões:</span>'+INTERVAL_PRESETS.map(([v,l])=>btn(l,'interval-preset','data-value="'+v+'"')).join('')+'</div><p class="tiny">Separe os dias por vírgula. Deixe vazio para não gerar lembretes. Alterações valem para novas sessões.</p>'+btn('Salvar meta e revisões','save-settings','','btn btn-primary'))+panel('Aparência','<p class="tiny">Escolha o tema. No automático, o app acompanha o claro ou escuro do seu aparelho.</p><div class="segmented" role="group" aria-label="Tema">'+[['light','Claro'],['dark','Escuro'],['auto','Automático']].map(([m,l])=>'<button type="button" data-action="theme-mode" data-mode="'+m+'" class="'+(themeMode()===m?'active':'')+'" aria-pressed="'+(themeMode()===m)+'">'+l+'</button>').join('')+'</div>')+panel('MedReview','<p class="tiny">Conecte sua conta e consulte o histórico de flashcards na tela Revisões.</p>'+btn('Abrir revisões','navigate','data-page="reviews"'))+'</div></div>'+scheduleSettings()+panel('Backup dos seus registros','<p class="tiny">'+(window.PlanningAccount?.enabled?'Tarefas, estudos e anotações acompanham sua conta. O backup permite guardar uma cópia independente.':'Tarefas, estudos e anotações ficam neste navegador. Baixe um backup antes de trocar de dispositivo.')+'</p><div class="pill-row">'+btn('Exportar backup JSON','backup','','btn btn-primary')+btn('Exportar estudos CSV','export-csv')+btn('Exportar calendário ICS','export-ics')+'</div><label class="field-label settings-restore">Restaurar um backup deste site<input type="file" id="json-upload" accept=".json,application/json" class="field"></label><p class="tiny">A restauração pede confirmação antes de substituir os registros atuais. O arquivo não inclui a sessão de login do MedReview.</p>')+'<details class="settings-fold"><summary><span>Trazer dados do planejamento antigo</span><small>Importação opcional</small></summary><div class="fold-content"><p class="tiny">Selecione a exportação JSON da aba Planejamento do projeto anterior. Você verá uma prévia antes de acrescentar os registros. Registros já importados não são duplicados.</p><label class="field-label">Exportação do planejamento antigo<input class="field" id="legacy-upload" type="file" accept=".json,application/json"></label></div></details><details class="settings-fold"><summary><span>Conexões Google</span><small>Opcional · planilha</small></summary><div class="fold-content" id="settings-connections"><p class="tiny">Estas conexões precisam de configuração e autorização da sua conta Google. Você também pode usar importação CSV e backup JSON sem conectá-las.</p></div></details>'}
function render(){nav();const views={today:todayView,week:calendar,calendar:semesterView,timeline:()=>(typeof timelineView==='function'?timelineView():semesterView()),tasks:tasksView,focus:focusView,studies:studiesView,reviews:reviewView,exams:examsView,reports:reportView,materials:materialsView,planner:plannerView,settings:settingsView};$('app').innerHTML=(views[page]||todayView)();renderAcademicStatus()}
function goto(p){if(p==='dashboard')p='today';page=p;render();window.scrollTo(0,0)}
const FORM={task:[['title','O que você vai fazer?','text',true],['subject','Disciplina / categoria','text'],['date','Prazo (opcional)','date'],['estimate','Duração estimada (min)','number'],['priority','Prioridade','select'],['repeat','Repetir','repeat'],['subtasks','Subtarefas (uma por linha, opcional)','textarea']],study:[['subject','Disciplina','text',true],['topic','Assunto efetivamente estudado','text',true],['date','Data','date',true],['minutes','Duração (min)','number',true],['questions','Questões (opcional)','number'],['correct','Acertos (opcional)','number']],event:[['title','Aula ou compromisso','text',true],['subject','Disciplina / categoria','text'],['date','Data','date',true],['from','Início','time'],['to','Fim','time'],['repeat','Repetir','eventrepeat'],['until','Repetir até (opcional; padrão 17 semanas)','date']],multitask:[['title','O que você vai fazer?','text',true],['subject','Disciplina / categoria','text'],['date','Primeiro dia','date',true],['until','Último dia','date',true],['wd','Dias da semana (sem marcar = todos os dias)','weekdays'],['estimate','Duração estimada por dia (min)','number'],['priority','Prioridade','select'],['subtasks','Subtarefas (uma por linha, opcional)','textarea']],exam:[['title','Avaliação','text',true],['subject','Disciplina','text'],['date','Data','date',true],['from','Início','time']],material:[['title','Material / referência','text',true],['subject','Disciplina','text'],['url','Link HTTPS','url']]};
function openForm(type,seed={}){let titles={multitask:'Tarefa em vários dias',task:seed.id?'Editar tarefa':'Criar tarefa',study:seed.id?'Editar estudo':'Registrar estudo',event:seed.id?'Editar compromisso':'Novo compromisso',exam:seed.id?'Editar avaliação':'Adicionar avaliação',material:'Adicionar material'};let fields=FORM[type].map(([name,label,kind,required])=>{if((kind==='eventrepeat'||name==='until')&&seed.id)return '';if(kind==='eventrepeat')return '<label class="field-label">'+label+'<select class="field" name="'+name+'"><option value="">Não repetir</option><option value="weekly">Toda semana (mesmo dia da semana)</option></select></label>';if(kind==='weekdays')return '<fieldset class="field-label field-wide"><legend>'+label+'</legend><div class="pill-row">'+[[1,'Seg'],[2,'Ter'],[3,'Qua'],[4,'Qui'],[5,'Sex'],[6,'Sáb'],[0,'Dom']].map(([i,l])=>'<label class="chip"><input type="checkbox" name="wd'+i+'" value="1"> '+l+'</label>').join('')+'</div></fieldset>';if(kind==='repeat')return '<label class="field-label">'+label+'<select class="field" name="'+name+'">'+[['','Não repetir'],['daily','Todos os dias'],['weekdays','Dias úteis (seg. a sex.)'],['weekly','Toda semana']].map(([v,l])=>'<option value="'+v+'" '+((seed[name]||'')===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label>';if(kind==='textarea')return '<label class="field-label field-wide">'+label+'<textarea class="field" name="'+name+'" rows="3" placeholder="Ex.: Ler o capítulo&#10;Fazer o resumo">'+esc(Array.isArray(seed[name])?seed[name].map(s=>s.title).join('\n'):(seed[name]||''))+'</textarea></label>';if(kind==='select')return '<label class="field-label">'+label+'<select class="field" name="'+name+'">'+[['1','Normal'],['2','Média'],['3','Alta']].map(([v,label])=>'<option value="'+v+'" '+(String(seed[name]||'1')===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label>';return '<label class="field-label">'+label+'<input class="field" type="'+kind+'" name="'+name+'" value="'+esc(seed[name]??(name==='date'&&type!=='task'?today():''))+'" '+(required?'required':'')+' '+(kind==='number'?'min="0" step="1"':'')+'></label>'}).join('');$('modal').innerHTML='<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-label"><button type="button" class="close" data-action="close" aria-label="Fechar">×</button><h2 id="modal-label">'+titles[type]+'</h2><p>'+(type==='task'?'Escreva uma ação concreta. O prazo é opcional; a duração ajuda o planejador a encontrar um horário.':type==='multitask'?'Cria a mesma tarefa em vários dias, cada uma com o próprio prazo. Marque os dias da semana ou deixe em branco para todos os dias do período.':'Os registros serão salvos no seu planejamento.')+'</p><form id="record-form" data-type="'+type+'" data-id="'+esc(['task','study','event','exam'].includes(type)?seed.id||'':'')+'"><div class="form-grid">'+fields+'</div><div class="pill-row between compact"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn btn-primary" type="submit">Salvar registro</button></div></form></div>';$('modal').classList.remove('hidden');$('record-form').querySelector('input')?.focus()}
function closeModal(){$('modal').classList.add('hidden');$('modal').innerHTML=''}
function onSubmit(e){e.preventDefault();let form=e.target;if(form.id!=='record-form')return;let kind=form.dataset.type,r=Object.fromEntries(new FormData(form));Object.keys(r).forEach(k=>r[k]=String(r[k]).trim());if(kind==='study'){if(Number(r.minutes)<=0){notify('A duração precisa ser maior que zero.');return}if((r.questions==='')!==(r.correct==='')||Number(r.correct)>Number(r.questions)){notify('Informe questões e acertos juntos e valide os acertos.');return}const existing=form.dataset.id?data.sessions.find(x=>x.id===form.dataset.id):null;if(existing){Object.assign(existing,r);data.reviews.filter(rv=>rv.sessionId===existing.id&&!rv.done).forEach(rv=>{rv.subject=r.subject;rv.topic=r.topic});notify('Sessão de estudo atualizada.');}else{let rec={...r,id:uid()};data.sessions.push(rec);let intervals=String(data.settings.intervals).split(',').map(x=>Number(x.trim())).filter(x=>Number.isInteger(x)&&x>0&&x<=1000);for(let n of [...new Set(intervals)])data.reviews.push({id:uid(),sessionId:rec.id,subject:rec.subject,topic:rec.topic,due:dayAdd(rec.date,n),interval:n,done:false});if(intervals.length)notify('Sessão registrada e revisões geradas.');else notify('Sessão registrada.',{label:'Revisar em 7 dias',run:()=>createReview(rec.subject,rec.topic,dayAdd(rec.date,7),{sessionId:rec.id,interval:7})});}}else if(kind==='task'){if(r.estimate!==''&&Number(r.estimate)<=0){notify('Informe uma duração maior que zero ou deixe em branco.');return}const existing=form.dataset.id?data.tasks.find(x=>x.id===form.dataset.id):null;if(form.dataset.id&&!existing){notify('Esta tarefa não foi encontrada.');return}const previous=existing&&Array.isArray(existing.subtasks)?existing.subtasks:[];r.subtasks=String(r.subtasks||'').split('\n').map(l=>l.trim()).filter(Boolean).slice(0,30).map(title=>{const old=previous.find(s=>s.title===title);return old?{...old}:{id:uid(),title:title.slice(0,160),done:false}});if(!['daily','weekdays','weekly'].includes(r.repeat))r.repeat='';if(existing)Object.assign(existing,r);else data.tasks.push({...r,id:uid(),done:false});}else if(kind==='multitask'){if(r.estimate!==''&&Number(r.estimate)<=0){notify('Informe uma duração maior que zero ou deixe em branco.');return}if(r.until<r.date){notify('O último dia precisa ser igual ou posterior ao primeiro.');return}const picked=[0,1,2,3,4,5,6].filter(i=>r['wd'+i]),dates=[];for(let d=r.date;d<=r.until&&dates.length<120;d=dayAdd(d,1)){if(!picked.length||picked.includes(new Date(d+'T12:00:00Z').getUTCDay()))dates.push(d)}if(!dates.length){notify('Nenhum dia do período corresponde aos dias da semana escolhidos.');return}const group=uid(),subs=String(r.subtasks||'').split('\n').map(l=>l.trim()).filter(Boolean).slice(0,30);for(const d of dates){const t={title:r.title,subject:r.subject,estimate:r.estimate,priority:r.priority,date:d,repeat:'',id:uid(),done:false,groupId:group};if(subs.length)t.subtasks=subs.map(title=>({id:uid(),title:title.slice(0,160),done:false}));data.tasks.push(t)}notify(dates.length+(dates.length===1?' tarefa criada.':' tarefas criadas.')+(dates.length>=120?' Limite de 120 dias.':''))}else if(kind==='material'){if(r.url&&!/^https:\/\//i.test(r.url)){notify('Informe apenas links HTTPS.');return}data.materials.push({...r,id:uid()})}else {if(r.from&&r.to&&r.from>=r.to){notify('Horário de término deve ser posterior ao início.');return}const existing=form.dataset.id?data.events.find(x=>x.id===form.dataset.id):null;const rule=r.repeat,until=r.until;delete r.repeat;delete r.until;if(existing){Object.assign(existing,r);notify('Compromisso atualizado.');}else{const dates=kind==='event'&&rule==='weekly'?(()=>{const out=[],end=until&&until>=r.date?until:dayAdd(r.date,119);for(let d=r.date;d<=end&&out.length<60;d=dayAdd(d,7))out.push(d);return out})():[r.date],sid=dates.length>1?uid():'';for(const d of dates)data.events.push({...r,date:d,id:uid(),type:kind==='exam'?'exam':'class',origin:'local',...(sid?{seriesId:sid}:{})});if(dates.length>1)notify(dates.length+' ocorrências semanais criadas.')}}save();closeModal();render()}
function remove(kind,id){if(!confirm('Excluir somente este registro local?'))return;let field={study:'sessions',material:'materials',task:'tasks'}[kind];if(!field)return;data[field]=data[field].filter(x=>x.id!==id);if(kind==='study')data.reviews=data.reviews.filter(x=>x.sessionId!==id);save();render()}
